"""Build a local, dependency-free listening page for the delivered A06 files."""
from pathlib import Path
import json
H=Path(__file__).resolve().parent
m=json.loads((H/'MANIFEST.json').read_text());requests=json.loads((H/'REQUESTS.json').read_text());prompts=json.loads((H/'PROMPTS.json').read_text());by={r['key']:r for r in requests}
rows=[dict(**r,group=by[r['key']]['group'],variants=[g['file'] for g in sorted((g for g in prompts['generations'] if g['key']==r['key']),key=lambda g:g['variant'])]) for r in m]
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>A06 Sound Audition</title><style>
:root{color-scheme:dark;font:16px system-ui;background:#261e30;color:#fff2dc}body{max-width:980px;margin:auto;padding:24px}h1{font-size:28px;margin-bottom:8px}p{color:#d1c3d2}button{border:1px solid #80677c;background:#423039;color:#fff2dc;border-radius:12px;padding:10px 14px;cursor:pointer}button:hover{border-color:#f4d9a1}nav{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0}section{border:1px solid #6d536d;border-radius:18px;margin:18px 0;padding:16px}article{display:flex;flex-wrap:wrap;align-items:center;gap:8px;border-top:1px solid #544253;padding:12px 0}.title{flex:1 1 240px}.meta{color:#bdb0c0;font-size:13px;margin-top:4px}details{width:100%;color:#c9b8cb}audio{width:100%}header.player{position:sticky;top:0;background:#261e30f5;border:1px solid #80677c;padding:14px;border-radius:14px;z-index:2}#now{margin-bottom:8px;color:#85d5b2}small{color:#c7b4ca}</style>
<h1>A06 · New feature sounds</h1><p>28 delivered cues · Original ElevenLabs Sound Effects · Phone listening review pending.</p><header class="player"><div id="now">Choose a sound</div><audio id="audio" controls preload="none"></audio><button id="stop">Stop</button></header><nav id="nav"></nav><main id="sets"></main><script>
const rows=DATA;const groups={A:'Forge',B:'Merge rarity',C:'Relic synergy',D:'Status effects',E:'Yuzu',F:'Taro Sentry',G:'Login & Depths'};const audio=document.querySelector('#audio'),now=document.querySelector('#now');let queue=[];
function play(list){queue=list.slice();next()}function next(){if(!queue.length)return;const r=queue.shift();audio.src=r.file;now.textContent=r.label;audio.play().catch(()=>{now.textContent='Press play to listen: '+r.label})}audio.onended=()=>setTimeout(next,300);document.querySelector('#stop').onclick=()=>{queue=[];audio.pause();audio.currentTime=0};
function button(label,fn){const b=document.createElement('button');b.textContent=label;b.onclick=fn;return b}const pretty=k=>k.replace(/^sfx_/,'').replaceAll('_',' ');
for(const [g,title] of Object.entries(groups)){const section=document.createElement('section');section.id='group'+g;const h=document.createElement('h2');h.textContent=title;section.append(h);const list=rows.filter(r=>r.group===g);section.append(button('Play '+title,()=>play(list.map(r=>({file:r.file,label:pretty(r.key)})))));if(g==='B'){section.append(button('Compare Legend → Divine',()=>play([{file:'../../audio/menu_progress/sfx_merge_rarity_legend.mp3',label:'Legend · existing game cue'},...list.map(r=>({file:r.file,label:pretty(r.key)}))])))}if(g==='E'){section.append(button('Compare Grow → Form 2 → Form 3',()=>play([{file:'../../audio/yuzu/sfx_yz_grow.mp3',label:'Grow · existing game cue'},...list.filter(r=>r.key.includes('evolve')).map(r=>({file:r.file,label:pretty(r.key)}))])))}for(const r of list){const a=document.createElement('article'),t=document.createElement('div');t.className='title';t.textContent=pretty(r.key);const meta=document.createElement('div');meta.className='meta';meta.textContent=(r.durationMs/1000).toFixed(2)+'s · '+r.lufsS+' LUFS-S · '+r.peakDbtp+' dBTP';t.append(meta);a.append(t,button('Play final',()=>play([{file:r.file,label:pretty(r.key)}])));const d=document.createElement('details'),s=document.createElement('summary');s.textContent='Compare raw alternatives';d.append(s);const p=document.createElement('p');p.textContent='Raw donors are unmastered and may differ in level.';d.append(p);r.variants.forEach((file,i)=>d.append(button('Take '+(i+1),()=>play([{file,label:pretty(r.key)+' · raw take '+(i+1)}]))));a.append(d);section.append(a)}document.querySelector('#sets').append(section);document.querySelector('#nav').append(button(title,()=>section.scrollIntoView({behavior:'smooth',block:'center'})))}
</script></html>'''.replace('DATA',json.dumps(rows,ensure_ascii=False))
(H/'AUDITION.html').write_text(html,encoding='utf8')
print('Built AUDITION.html with',len(rows),'cues')
